  POLYBENCH_DUMP_FINISH;
}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *
from exo.stdlib.scheduling import *
from exo.stdlib.stdlib import *


# Base ADI kernel: direct, readable implementation.
@proc
def kernel_adi_base(
    tsteps: size,
    n: size,
    mul1: DATA_TYPE,
    mul2: DATA_TYPE,
    u: DATA_TYPE[n, n] @ DRAM,
    v: DATA_TYPE[n, n] @ DRAM,
    p: DATA_TYPE[n, n] @ DRAM,
    q: DATA_TYPE[n, n] @ DRAM,
):
    # We update interior points (indices 1..n-2), so we need at least 3 points.
    assert n > 2

    # Coefficients derived from the time/space steps.
    a: DATA_TYPE
    b: DATA_TYPE
    c: DATA_TYPE
    d: DATA_TYPE
    e: DATA_TYPE
    f: DATA_TYPE

    # Precomputed combinations used inside the sweeps.
    # Hoisting these out of the loops reduces redundant arithmetic
    # while keeping results bit-identical (they depend only on mul1/mul2).
    one_plus_2a: DATA_TYPE
    one_plus_2d: DATA_TYPE

    a = -mul1 / 2.0
    b = 1.0 + mul1
    c = a
    d = -mul2 / 2.0
    e = 1.0 + mul2
    f = d

    one_plus_2a = 1.0 + 2.0 * a
    one_plus_2d = 1.0 + 2.0 * d

    for t in seq(1, tsteps + 1):
        # ------------------------------------------------------------------
        # Column sweep: for each interior column i we solve a tridiagonal
        # system along the j-direction (forward elimination + back-solve).
        # Each column is independent and only reads u[:, i-1..i+1].
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            # Dirichlet boundary at the top of column i.
            v[0, i] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = v[0, i]

            # Local denominator reused in both p and q updates.
            # Keeping it local to the i-iteration is important for
            # parallelization: it becomes thread-private.
            denom: DATA_TYPE

            # Forward sweep along j.
            for j in seq(1, n - 1):
                # Common denominator for p[i, j] and q[i, j].
                denom = a * p[i, j - 1] + b

                p[i, j] = -c / denom
                q[i, j] = (
                    -d * u[j, i - 1]
                    + one_plus_2d * u[j, i]
                    - f * u[j, i + 1]
                    - a * q[i, j - 1]
                ) / denom

            # Dirichlet boundary at the bottom of column i.
            v[n - 1, i] = 1.0

            # Back substitution along j (still within column i).
            for j in seq(1, n - 1):
                v[n - 1 - j, i] = (
                    p[i, n - 1 - j] * v[n - j, i]
                    + q[i, n - 1 - j]
                )

        # ------------------------------------------------------------------
        # Row sweep: for each interior row i we solve a tridiagonal
        # system along the j-direction using v as input and writing u.
        # Each row is independent and only reads v[i-1..i+1, :].
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            # Dirichlet boundary at the left of row i.
            u[i, 0] = 1.0
            p[i, 0] = 0.0
            q[i, 0] = u[i, 0]

            # Again, keep denominator local to enable safe parallelization.
            denom_row: DATA_TYPE

            # Forward sweep along j on row i.
            for j in seq(1, n - 1):
                denom_row = d * p[i, j - 1] + e

                p[i, j] = -f / denom_row
                q[i, j] = (
                    -a * v[i - 1, j]
                    + one_plus_2a * v[i, j]
                    - c * v[i + 1, j]
                    - d * q[i, j - 1]
                ) / denom_row

            # Dirichlet boundary at the right of row i.
            u[i, n - 1] = 1.0

            # Back substitution along j (within row i).
            for j in seq(1, n - 1):
                u[i, n - 1 - j] = (
                    p[i, n - 1 - j] * u[i, n - j]
                    + q[i, n - 1 - j]
                )


# ----------------------------------------------------------------------
# Scheduling: create an optimized version of the kernel.
# We preserve the mathematical computation but:
#   * simplify the IR,
#   * parallelize the sweeps over i (independent columns/rows).
# ----------------------------------------------------------------------

# Start from the base kernel and give the final procedure the name
# expected by the C driver: "kernel_adi".
kernel_adi = rename(kernel_adi_base, "kernel_adi")

# Perform generic simplifications (constant folding, dead branch removal, etc.).
kernel_adi = simplify(kernel_adi)

# Parallelize the column sweep over i (first i-loop inside the t-loop).
# Each column uses disjoint slices of v, p, q and only reads u, so there
# are no loop-carried dependences across different values of i.
kernel_adi = parallelize_loop(kernel_adi, "i")

# Parallelize the row sweep over i (second i-loop inside the t-loop).
# Each row uses disjoint slices of u, p, q and only reads v, so it is
# likewise safe to parallelize.
kernel_adi = parallelize_loop(kernel_adi, "i #1")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int tsteps = TSTEPS;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(u, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(v, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(p, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(q, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(u));

  /* Precompute scalar coefficients used by the Exo kernel. */
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;

  DX = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DY = SCALAR_VAL(1.0) / (DATA_TYPE)n;
  DT = SCALAR_VAL(1.0) / (DATA_TYPE)tsteps;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_adi(/*ctxt=*/NULL,
             tsteps, n,
             (DATA_TYPE*)&mul1, (DATA_TYPE*)&mul2,
             (DATA_TYPE*)POLYBENCH_ARRAY(u),
             (DATA_TYPE*)POLYBENCH_ARRAY(v),
             (DATA_TYPE*)POLYBENCH_ARRAY(p),
             (DATA_TYPE*)POLYBENCH_ARRAY(q));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(u)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(u);
  POLYBENCH_FREE_ARRAY(v);
  POLYBENCH_FREE_ARRAY(p);
  POLYBENCH_FREE_ARRAY(q);

  return 0;
}
